CREATE OR REPLACE FUNCTION public.sb_resolve_companies(tickers text[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r jsonb; BEGIN IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; PERFORM public.sb_rate_limit(); IF coalesce(cardinality(tickers),0) NOT BETWEEN 1 AND 200 OR EXISTS(SELECT 1 FROM unnest(tickers) t WHERE t IS NULL OR t !~ '^[A-Za-z0-9.:-]{1,32}$') THEN RAISE EXCEPTION 'invalid_tickers' USING ERRCODE='PT422'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'ticker',c.ticker,'market',c.market,'provider',c.provider,'is_demo',c.is_demo,'last_ingested_at',c.last_ingested_at) ORDER BY c.name),'[]'::jsonb) INTO r FROM public.companies c WHERE NOT c.is_demo AND upper(c.ticker) IN(SELECT upper(t) FROM unnest(tickers) t); RETURN r; END $$;
REVOKE ALL ON FUNCTION public.sb_resolve_companies(text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_resolve_companies(text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.sb_admin_catalog_sync(provider text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;jid text;dkey text;BEGIN IF NOT app_private.sb_is_admin() THEN RAISE EXCEPTION 'admin_required' USING ERRCODE='PT403'; END IF; PERFORM public.sb_rate_limit();IF provider IS NULL OR provider NOT IN ('dart','sec') THEN RAISE EXCEPTION 'invalid_provider' USING ERRCODE='PT422';END IF;dkey:='catalog:'||provider||':'||to_char(now(),'YYYYMMDD');INSERT INTO public.jobs(id,kind,dedupe_key,payload,state,attempts,max_attempts,available_at,created_at) VALUES(gen_random_uuid()::text,'sync_companies',dkey,jsonb_build_object('provider',provider)::json,'queued',0,5,now(),now()) ON CONFLICT(dedupe_key) DO NOTHING;SELECT id INTO jid FROM public.jobs WHERE dedupe_key=dkey;INSERT INTO public.audit_logs(id,actor_id,action,target_id,details,created_at) VALUES(gen_random_uuid()::text,u,'sync_catalog',jid,jsonb_build_object('provider',provider)::json,now());RETURN jsonb_build_object('job_id',jid,'processing_active',false,'note','Queued; the Python worker must be configured before processing.');END $$;
REVOKE ALL ON FUNCTION public.sb_admin_catalog_sync(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_admin_catalog_sync(text) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.sb_default_alert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE threshold double precision;BEGIN IF NEW.onboarding_completed AND NOT OLD.onboarding_completed AND NOT EXISTS(SELECT 1 FROM public.alerts WHERE user_id=NEW.id) THEN SELECT CASE alert_frequency WHEN 'essential' THEN 0.7 WHEN 'normal' THEN 0.4 ELSE 0.0 END INTO threshold FROM public.user_preferences WHERE user_id=NEW.id;INSERT INTO public.alerts(id,user_id,name,event_types,min_score,enabled,created_at) VALUES(gen_random_uuid()::text,NEW.id,'내 종목의 중요한 변화','[]'::json,coalesce(threshold,0.7),true,now());END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS sb_onboard_default_alert ON public.users; CREATE TRIGGER sb_onboard_default_alert AFTER UPDATE OF onboarding_completed ON public.users FOR EACH ROW EXECUTE FUNCTION app_private.sb_default_alert();
CREATE OR REPLACE FUNCTION public.sb_save_answer(eid text,question text,reason text,fact_ids text[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;ev jsonb;result jsonb;allowed int;BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401';END IF;PERFORM public.sb_rate_limit();IF NOT app_private.sb_event_visible(eid) THEN RAISE EXCEPTION 'event_not_found' USING ERRCODE='PT404';END IF;IF length(trim(coalesce(question,''))) NOT BETWEEN 1 AND 2000 OR coalesce(reason,'') NOT IN ('current','changes','no_evidence','advice') OR coalesce(cardinality(fact_ids),0)>6 THEN RAISE EXCEPTION 'invalid_question' USING ERRCODE='PT422';END IF;SELECT count(*) INTO allowed FROM public.facts f WHERE f.id=ANY(fact_ids) AND f.validation_status='supported' AND app_private.sb_fact_visible(f.id) AND (f.event_id=eid OR EXISTS(SELECT 1 FROM public.changes c WHERE c.event_id=eid AND c.previous_fact_id=f.id));IF allowed<>coalesce(cardinality(fact_ids),0) OR (reason IN ('current','changes') AND allowed=0) OR (reason IN ('advice','no_evidence') AND allowed<>0) OR (reason='changes' AND NOT EXISTS(SELECT 1 FROM public.changes c WHERE c.event_id=eid AND c.current_fact_id=ANY(fact_ids) AND c.previous_fact_id=ANY(fact_ids))) THEN RAISE EXCEPTION 'invalid_evidence' USING ERRCODE='PT422';END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('source_id',f.id,'quote',f.quote,'source_url',d.source_url,'location',c.location) ORDER BY array_position(fact_ids,f.id)),'[]') INTO ev FROM public.facts f JOIN public.document_chunks c ON c.id=f.chunk_id JOIN public.documents d ON d.id=c.document_id WHERE f.id=ANY(fact_ids);result:=jsonb_build_object('status',CASE reason WHEN 'advice' THEN 'policy_blocked' WHEN 'no_evidence' THEN 'abstained' ELSE 'answered' END,'message',CASE reason WHEN 'current' THEN '질문과 관련된 검증된 원문 인용입니다. 새로운 해석이나 주가 전망을 생성하지 않았습니다.' WHEN 'changes' THEN '이전과 현재를 비교할 수 있는 원문 근거입니다. 각 인용의 기간과 단위를 함께 확인하세요.' WHEN 'advice' THEN '매매 추천, 목표주가, 확정적인 수익률 전망은 제공하지 않습니다. 공시의 사실과 변경점을 질문해 주세요.' ELSE '제공된 공시 근거만으로 이 질문에 답하기 어렵습니다. 확인되지 않은 내용은 추측하지 않습니다.' END,'evidence',ev,'run_id',NULL,'mode','extractive');PERFORM 1 FROM public.users WHERE id=u FOR UPDATE;IF (SELECT count(*) FROM public.question_history WHERE user_id=u)>=2000 THEN RAISE EXCEPTION 'question_history_limit_delete_old_history' USING ERRCODE='PT422';END IF;INSERT INTO public.question_history(user_id,event_id,question,answer) VALUES(u,eid,question,result);RETURN result;END $$;
REVOKE ALL ON FUNCTION public.sb_save_answer(text,text,text,text[]) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.sb_save_answer(text,text,text,text[]) TO authenticated;
NOTIFY pgrst,'reload schema';